values.value:
{
  "fields": [
    {
      "apiName": "MBCB_PGR_folder_1",
      "label": "Pedestrian Guard Rail Details",
      "type": "folder",
      "iconColor": "blue",
      "controllingField": "MBCB_Type",
      "controllingValues": [
        "Pedestrian Guard Rail"
      ],
      "modalConfigsByValue": {
        "Pedestrian Guard Rail": {
          "title": "GENERAL DETAILS - Pedestrian Guard Rail",
          "modalFields": [
            {
              "id": "std_general_details",
              "label": "General Details",
              "expanded": true,
              "fields": [
                {
                  "apiName": "PGR_itemName_header",
                  "label": "Item Name",
                  "type": "header",
                  "colSpan": 6
                },
                {
                  "apiName": "PGR_itemName",
                  "label": "",
                  "type": "text",
                  "defaultValue": "PEDESTRIAN GUARD RAIL (AS PER DRAWING)",
                  "required": true,
                  "colSpan": 6
                },
                {
                  "apiName": "PGR_Quantity_header",
                  "label": "Quantity",
                  "type": "header",
                  "colSpan": 6
                },
                {
                  "apiName": "PGR_Quantity",
                  "label": "",
                  "type": "number",
                  "isQuantity": true,
                  "required": true,
                  "colSpan": 6
                },
                {
                  "apiName": "PGR_Rate_header",
                  "label": "Rate",
                  "type": "header",
                  "colSpan": 6
                },
                {
                  "apiName": "PGR_Rate",
                  "label": "",
                  "type": "number",
                  "required": true,
                  "colSpan": 6
                },
                {
                  "apiName": "PGR_Realization_header",
                  "label": "Realization %",
                  "type": "header",
                  "colSpan": 6
                },
                {
                  "apiName": "PGR_Realization",
                  "label": "",
                  "type": "number",
                  "required": true,
                  "colSpan": 6
                },
                {
                  "apiName": "PGR_trans_in_offer_header",
                  "label": "Trans.in offer?",
                  "type": "header",
                  "colSpan": 6
                },
                {
                  "apiName": "PGR_trans_in_offer",
                  "label": "",
                  "type": "picklist",
                  "pushToParentApiName": "freight_incoterms",
                  "options": [
                    "Ex-works",
                    "F.O.R (Freight on Road)"
                  ],
                  "colSpan": 6
                },


                {
                  "apiName": "PGR_fvf_header",
                  "label": "Full Vehicle Freight",
                  "type": "header",
                  "controllingField": "PGR_trans_in_offer",
                  "controllingValues": [
                    "F.O.R (Freight on Road)"
                  ],
                  "colSpan": 6
                },
                {
                  "apiName": "PGR_full_vehicle_freight",
                  "label": "",
                  "type": "number",
                  "min": 1,
                  "required":true,
                  "controllingField": "PGR_trans_in_offer",
                  "controllingValues": [
                    "F.O.R (Freight on Road)"
                  ],
                  "colSpan": 6
                },
                {
                  "apiName": "PGR_pricing_sub",
                  "label": "Amount Calculation",
                  "type": "sub-section",
                  "expanded": false,
                  "fields": [
                    {
                      "apiName": "PGR_total_amount",
                      "label": "Total Amount",
                      "formula": "(PGR_Quantity*PGR_Rate)",
                      "type": "number",
                      "isUnitCost": true,
                      "readOnly": true,
                      "colSpan": 12
                    },
                    {
                      "apiName": "PGR_total_amount_wp",
                      "label": "Total Amount with Profit",
                      "formula": "(PGR_Quantity*PGR_Rate)*(1+PGR_Realization/100)",
                      "type": "number",
                      "isUnitPrice": true,
                      "readOnly": true,
                      "colSpan": 12
                    }
                  ]
                }
              ]
            }
          ]
        }
      }
    }
  ]
}
